            <div class="filter-buttons">
                <button class="filter-btn active" id="btn-filter-all" onclick="setFilter('all')">
                    <i class="fa-solid fa-border-all"></i> الكل (<span id="count-all">0</span>)
                </button>
                <button class="filter-btn img-filter" id="btn-filter-images" onclick="setFilter('images')">
                    <i class="fa-solid fa-image"></i> الصور (<span id="count-images">0</span>)
                </button>
                <button class="filter-btn pdf-filter" id="btn-filter-pdfs" onclick="setFilter('pdfs')">
                    <i class="fa-solid fa-file-pdf"></i> ملفات PDF (<span id="count-pdfs">0</span>)
                </button>
            </div>
        </div>

        <!-- شبكة عرض العناصر -->
        <div class="media-grid" id="mediaGrid">
            <!-- سيتم توليد العناصر هنا ديناميكياً بواسطة JavaScript -->
        </div>
    </div>

    <!-- ===== Lightbox Modal للصور ===== -->
    <div class="lightbox-modal" id="imageModal">
        <div class="lightbox-header">
            <div class="lightbox-title" id="imageModalTitle">
                <i class="fa-solid fa-image" style="color: var(--image-color);"></i>
                <span>عنوان الصورة</span>
            </div>
            <div class="lightbox-controls">
                <button class="icon-btn zoom-ctrl" onclick="zoomImage(0.2)" title="تكبير (+)"><i
                        class="fa-solid fa-magnifying-glass-plus"></i></button>
                <button class="icon-btn zoom-ctrl" onclick="zoomImage(-0.2)" title="تصغير (-)"><i
                        class="fa-solid fa-magnifying-glass-minus"></i></button>
                <button class="icon-btn zoom-ctrl" onclick="rotateImage(90)" title="تدوير 90 درجة"><i
                        class="fa-solid fa-rotate-right"></i></button>
                <button class="icon-btn zoom-ctrl" onclick="resetImageTransform()" title="إعادة ضبط"><i
                        class="fa-solid fa-arrows-rotate"></i></button>
                <a class="icon-btn" id="imageDownloadBtn" download title="تحميل الصورة" target="_blank"><i
                        class="fa-solid fa-download"></i></a>
                <button class="icon-btn close-modal-btn" onclick="closeImageModal()" title="إغلاق (Esc)"><i
                        class="fa-solid fa-xmark"></i></button>
            </div>
        </div>
        <div class="lightbox-body" id="lightboxBody">
            <div class="lightbox-img-wrapper" id="imgWrapper">
                <img id="modalImg" src="" alt="معاينة الصورة" onerror="handleImgError(this)">
            </div>
            <iframe class="pdf-modal-frame" id="imageIframe" style="display:none;"></iframe>
        </div>
    </div>

    <!-- ===== Modal عارض PDF ===== -->
    <div class="lightbox-modal" id="pdfModal">
        <div class="lightbox-header">
            <div class="lightbox-title" id="pdfModalTitle">
                <i class="fa-solid fa-file-pdf" style="color: var(--pdf-color);"></i>
                <span>عنوان ملف PDF</span>
            </div>
            <div class="lightbox-controls">
                <a class="icon-btn" id="pdfOpenExternalBtn" target="_blank" title="فتح في نافذة جديدة"><i
                        class="fa-solid fa-up-right-from-square"></i></a>
                <a class="icon-btn" id="pdfDownloadBtn" download title="تحميل المستند" target="_blank"><i
                        class="fa-solid fa-download"></i></a>
                <button class="icon-btn close-modal-btn" onclick="closePdfModal()" title="إغلاق"><i
                        class="fa-solid fa-xmark"></i></button>
            </div>
        </div>
        <iframe class="pdf-modal-frame" id="pdfIframe" src=""></iframe>
    </div>

    <footer>
        جميع الحقوق محفوظة &copy; 2026 | عارض المستندات والصور
    </footer>

    <script>
        // مصفوفة البيانات العامة
        let allItems = [];
        let currentFilter = 'all';

        // حالات تكبير وتدوير الصورة في الـ Lightbox
        let currentScale = 1;
        let currentRotate = 0;
        let isDragging = false;
        let startX = 0, startY = 0;
        let translateX = 0, translateY = 0;

        // عند تحميل الصفحة
        document.body.onload = function () {
            loadPredefinedData();
            setupDragAndDrop();
            setupKeyboardShortcuts();
        };

        // 1. تحميل البيانات من ملف PDF-images.json إن وجد
        async function loadPredefinedData() {
            try {
                const response = await fetch('PDF-images.json');
                if (response.ok) {
                    const data = await response.json();
                    parseJsonData(data);
                } else {
                    console.log('لم يتم العثور على PDF-images.json، سيتم استخدام البيانات الافتراضية.');
                    loadDefaultSamples();
                }
            } catch (err) {
                console.warn('تعذر قراءة ملف JSON محلي، جاري تحميل أمثلة التوضيح:', err);
                loadDefaultSamples();
            }
            renderGrid();
        }

        function parseJsonData(data) {
            allItems = [];
            let list = Array.isArray(data) ? data : [data];

            list.forEach(block => {
                // استخراج الصور
                if (block.images && Array.isArray(block.images)) {
                    block.images.forEach(img => {
                        allItems.push({
                            id: img.id || 'img-' + Math.random().toString(36).substr(2, 9),
                            title: img.title || 'صورة بدون عنوان',
                            type: 'image',
                            url: img.url,
                            source: 'remote'
                        });
                    });
                }

                // استخراج ملفات PDF
                if (block.pdfs && Array.isArray(block.pdfs)) {
                    block.pdfs.forEach(pdf => {
                        let finalUrl = pdf.url || (pdf.links && pdf.links[0] ? pdf.links[0].url : '');
                        let title = pdf.title || (pdf.links && pdf.links[0] ? pdf.links[0].text : 'مستند PDF');
                        if (finalUrl) {
                            allItems.push({
                                id: pdf.id || 'pdf-' + Math.random().toString(36).substr(2, 9),
                                title: title,
                                type: 'pdf',
                                url: finalUrl,
                                source: 'remote'
                            });
                        }
                    });
                }
            });

            if (allItems.length === 0) {
                loadDefaultSamples();
            }
        }

        function loadDefaultSamples() {
            allItems = [
                {
                    id: 'sample-1',
                    title: 'صينية كيمر من 2022',
                    type: 'image',
                    url: 'https://drive.google.com/file/d/1P091WSBMzAOxoQZEfFSzmQnqOmeuz19m/view?usp=sharing',
                    source: 'remote'
                },
                {
                    id: 'sample-2',
                    title: 'مخطط خلفية القوة والضعف',
                    type: 'image',
                    url: 'https://placehold.co/800x450/1a1a2e/00ff88.png?text=مخطط+خلفية+القوة',
                    source: 'remote'
                },
                {
                    id: 'sample-3',
                    title: 'مكتبة موجات اليوت (PDF)',
                    type: 'pdf',
                    url: 'https://drive.google.com/file/d/1ECixmzgRdoFAx2VlIph_5lcVTItJYdEL/view?usp=sharing',
                    source: 'remote'
                }
            ];
        }

        // 2. معالجة سحب وإفلات أو رفع الملفات المحلية
        function setupDragAndDrop() {
            const dropzone = document.getElementById('dropzone');

            ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
                dropzone.addEventListener(eventName, preventDefaults, false);
            });

            function preventDefaults(e) {
                e.preventDefault();
                e.stopPropagation();
            }

            ['dragenter', 'dragover'].forEach(eventName => {
                dropzone.addEventListener(eventName, () => dropzone.classList.add('dragover'), false);
            });

            ['dragleave', 'drop'].forEach(eventName => {
                dropzone.addEventListener(eventName, () => dropzone.classList.remove('dragover'), false);
            });

            dropzone.addEventListener('drop', (e) => {
                const files = e.dataTransfer.files;
                processUploadedFiles(files);
            });
        }

        function handleFileSelect(event) {
            const files = event.target.files;
            processUploadedFiles(files);
        }

        function processUploadedFiles(files) {
            if (!files || files.length === 0) return;

            Array.from(files).forEach(file => {
                const isPdf = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
                const isImg = file.type.startsWith('image/') || /\.(jpg|jpeg|png|webp|gif|svg)$/i.test(file.name);

                if (!isPdf && !isImg) {
                    alert(`الملف "${file.name}" ليس صورة أو مستند PDF مدعوم.`);
                    return;
                }

                const fileUrl = URL.createObjectURL(file);
                allItems.unshift({
                    id: 'local-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5),
                    title: file.name,
                    type: isPdf ? 'pdf' : 'image',
                    url: fileUrl,
                    source: 'local',
                    size: formatBytes(file.size)
                });
            });

            renderGrid();
        }

        function formatBytes(bytes) {
            if (!bytes || bytes === 0) return 'حجم غير معروف';
            const k = 1024;
            const sizes = ['B', 'KB', 'MB', 'GB'];
            const i = Math.floor(Math.log(bytes) / Math.log(k));
            return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
        }

        // 3. فلترة وعرض العناصر في الشبكة
        function setFilter(filter) {
            currentFilter = filter;
            document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));

            if (filter === 'all') document.getElementById('btn-filter-all').classList.add('active');
            if (filter === 'images') document.getElementById('btn-filter-images').classList.add('active');
            if (filter === 'pdfs') document.getElementById('btn-filter-pdfs').classList.add('active');

            renderGrid();
        }

        function filterMedia() {
            renderGrid();
        }

        const FALLBACK_SVG = `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="600" height="400" viewBox="0 0 600 400"><rect width="100%" height="100%" fill="%2318181c"/><text x="50%" y="50%" fill="%23ff4757" font-family="sans-serif" font-size="20" text-anchor="middle" dominant-baseline="middle">تعذر تحميل الصورة</text></svg>`;

        function extractDriveId(url) {
            if (!url || typeof url !== 'string') return null;
            const matchD = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
            if (matchD && matchD[1]) return matchD[1];
            const matchId = url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
            if (matchId && matchId[1]) return matchId[1];
            return null;
        }

        function handleImgError(imgEl, originalUrl) {
            imgEl.onerror = null;
            const raw = originalUrl || imgEl.dataset.rawUrl || imgEl.src;
            const driveId = extractDriveId(raw);
            if (driveId && !imgEl.dataset.triedLh3) {
                imgEl.dataset.triedLh3 = 'true';
                imgEl.src = `https://lh3.googleusercontent.com/d/${driveId}`;
                imgEl.onerror = function () {
                    this.onerror = null;
                    this.src = FALLBACK_SVG;
                };
            } else {
                imgEl.src = FALLBACK_SVG;
            }
        }

        function getDirectImageUrl(url) {
            if (!url) return 'https://placehold.co/600x400/18181c/00d4ff.png?text=صورة';
            if (url.includes('via.placeholder.com')) {
                let clean = url.replace('via.placeholder.com', 'placehold.co');
                if (!clean.includes('?') && !clean.endsWith('.png')) clean += '.png';
                return clean;
            }
            if (url.includes('drive.google.com')) {
                const driveId = extractDriveId(url);
                if (driveId) {
                    return `https://drive.google.com/thumbnail?id=${driveId}&sz=w800`;
                }
            }
            return url;
        }

        function getDirectPdfUrl(url) {
            if (!url) return '';
            if (url.includes('drive.google.com')) {
                const driveId = extractDriveId(url);
                if (driveId) {
                    return `https://drive.google.com/file/d/${driveId}/preview`;
                }
            }
            return url;
        }

        function renderGrid() {
            const grid = document.getElementById('mediaGrid');
            const searchQuery = document.getElementById('searchInput').value.trim().toLowerCase();

            // تحديث العدادات
            const totalImages = allItems.filter(i => i.type === 'image').length;
            const totalPdfs = allItems.filter(i => i.type === 'pdf').length;
            document.getElementById('count-all').innerText = allItems.length;
            document.getElementById('count-images').innerText = totalImages;
            document.getElementById('count-pdfs').innerText = totalPdfs;

            // الفلترة
            let filtered = allItems.filter(item => {
                const matchesFilter = (currentFilter === 'all') ||
                    (currentFilter === 'images' && item.type === 'image') ||
                    (currentFilter === 'pdfs' && item.type === 'pdf');
                const matchesSearch = item.title.toLowerCase().includes(searchQuery);
                return matchesFilter && matchesSearch;
            });

            grid.innerHTML = '';

            if (filtered.length === 0) {
                grid.innerHTML = `
                    <div class="empty-state">
                        <i class="fa-regular fa-folder-open"></i>
                        <h3>لا توجد ملفات مطابقة للبحث أو الفلتر</h3>
                        <p>قم بسحب ملفاتك وإسقاطها في المنطقة العلوية لعرضها فوراً.</p>
                    </div>
                `;
                return;
            }

            filtered.forEach(item => {
                const card = document.createElement('div');
                card.className = `media-card ${item.type === 'pdf' ? 'pdf-card' : ''}`;

                if (item.type === 'image') {
                    const displayImgUrl = getDirectImageUrl(item.url);
                    const safeTitle = escapeQuotes(item.title);
                    const safeUrl = escapeQuotes(item.url);
                    card.innerHTML = `
                        <div class="card-preview" onclick="openImageModal('${displayImgUrl}', '${safeTitle}', '${safeUrl}')">
                            <span class="type-badge badge-image"><i class="fa-solid fa-image"></i> صورة</span>
                            ${item.source === 'local' ? '<span class="type-badge badge-local">محلي</span>' : ''}
                            <img src="${displayImgUrl}" alt="${safeTitle}" onerror="handleImgError(this, '${safeUrl}')">
                        </div>
                        <div class="card-body">
                            <div class="card-title" title="${safeTitle}">${item.title}</div>
                            <div class="card-meta">
                                <span><i class="fa-solid fa-file-image"></i> ملف صورة</span>
                                <span>${item.size || 'عن بُعد'}</span>
                            </div>
                            <div class="card-actions">
                                <button class="action-btn" onclick="openImageModal('${displayImgUrl}', '${safeTitle}', '${safeUrl}')">
                                    <i class="fa-solid fa-eye"></i> معاينة مكبرة
                                </button>
                                <a class="action-btn" href="${displayImgUrl}" target="_blank" download>
                                    <i class="fa-solid fa-download"></i>
                                </a>
                            </div>
                        </div>
                    `;
                } else {
                    const pdfEmbedUrl = getDirectPdfUrl(item.url);
                    card.innerHTML = `
                        <div class="card-preview" onclick="openPdfModal('${pdfEmbedUrl}', '${escapeQuotes(item.title)}', '${item.url}')">
                            <span class="type-badge badge-pdf"><i class="fa-solid fa-file-pdf"></i> PDF</span>
                            ${item.source === 'local' ? '<span class="type-badge badge-local">محلي</span>' : ''}
                            <div class="pdf-preview-box">
                                <i class="fa-solid fa-file-pdf"></i>
                                <span style="font-size:0.85rem; font-weight:700;">انقر للفتح والمعاينة</span>
                            </div>
                        </div>
                        <div class="card-body">
                            <div class="card-title" title="${escapeQuotes(item.title)}">${item.title}</div>
                            <div class="card-meta">
                                <span><i class="fa-solid fa-file-lines"></i> مستند PDF</span>
                                <span>${item.size || 'عن بُعد'}</span>
                            </div>
                            <div class="card-actions">
                                <button class="action-btn pdf-btn" onclick="openPdfModal('${pdfEmbedUrl}', '${escapeQuotes(item.title)}', '${item.url}')">
                                    <i class="fa-solid fa-book-open"></i> قراءة الملف
                                </button>
                                <a class="action-btn pdf-btn" href="${item.url}" target="_blank" download>
                                    <i class="fa-solid fa-download"></i>
                                </a>
                            </div>
                        </div>
                    `;
                }

                grid.appendChild(card);
            });
        }

        function escapeQuotes(str) {
            return (str || '').replace(/'/g, "\\'").replace(/"/g, '&quot;');
        }

        // 4. Modal معاينة الصورة (Image Lightbox Engine)
        function openImageModal(imgUrl, title, rawUrl) {
            const fullUrl = rawUrl || imgUrl || '';
            const driveId = extractDriveId(fullUrl) || extractDriveId(imgUrl);
            const modalImg = document.getElementById('modalImg');
            const imgWrapper = document.getElementById('imgWrapper');
            const imageIframe = document.getElementById('imageIframe');
            const zoomControls = document.querySelectorAll('.zoom-ctrl');

            document.getElementById('imageModalTitle').querySelector('span').innerText = title;
            document.getElementById('imageDownloadBtn').href = fullUrl || imgUrl;

            if (driveId) {
                if (imageIframe) {
                    imageIframe.src = `https://drive.google.com/file/d/${driveId}/preview`;
                    imageIframe.style.display = 'block';
                }
                if (imgWrapper) imgWrapper.style.display = 'none';
                zoomControls.forEach(btn => btn.style.display = 'none');
            } else {
                if (imageIframe) {
                    imageIframe.src = '';
                    imageIframe.style.display = 'none';
                }
                if (imgWrapper) imgWrapper.style.display = 'flex';
                zoomControls.forEach(btn => btn.style.display = 'inline-flex');

                modalImg.dataset.rawUrl = fullUrl;
                modalImg.src = imgUrl;
                resetImageTransform();
            }

            const modal = document.getElementById('imageModal');
            modal.style.display = 'flex';
        }

        function closeImageModal() {
            document.getElementById('imageModal').style.display = 'none';
            const imageIframe = document.getElementById('imageIframe');
            if (imageIframe) imageIframe.src = '';
        }

        function zoomImage(amount) {
            currentScale = Math.max(0.4, Math.min(5, currentScale + amount));
            updateImageTransform();
        }

        function rotateImage(deg) {
            currentRotate = (currentRotate + deg) % 360;
            updateImageTransform();
        }

        function resetImageTransform() {
            currentScale = 1;
            currentRotate = 0;
            translateX = 0;
            translateY = 0;
            updateImageTransform();
        }

        function updateImageTransform() {
            const imgWrapper = document.getElementById('imgWrapper');
            imgWrapper.style.transform = `translate(${translateX}px, ${translateY}px) scale(${currentScale}) rotate(${currentRotate}deg)`;
        }

        // إمكانية سحب الصورة عند التكبير
        const lightboxBody = document.getElementById('lightboxBody');
        lightboxBody.addEventListener('mousedown', (e) => {
            if (currentScale > 1) {
                isDragging = true;
                startX = e.clientX - translateX;
                startY = e.clientY - translateY;
            }
        });

        window.addEventListener('mousemove', (e) => {
            if (isDragging) {
                translateX = e.clientX - startX;
                translateY = e.clientY - startY;
                updateImageTransform();
            }
        });

        window.addEventListener('mouseup', () => { isDragging = false; });

        // تكبير وتصغير بالماوس Wheel
        lightboxBody.addEventListener('wheel', (e) => {
            if (document.getElementById('imageModal').style.display === 'flex') {
                e.preventDefault();
                zoomImage(e.deltaY < 0 ? 0.15 : -0.15);
            }
        }, { passive: false });


        // 5. Modal معاينة PDF
        function openPdfModal(embedUrl, title, rawUrl) {
            const iframe = document.getElementById('pdfIframe');
            iframe.src = embedUrl;

            document.getElementById('pdfModalTitle').querySelector('span').innerText = title;
            document.getElementById('pdfOpenExternalBtn').href = rawUrl || embedUrl;
            document.getElementById('pdfDownloadBtn').href = rawUrl || embedUrl;

            document.getElementById('pdfModal').style.display = 'flex';
        }

        function closePdfModal() {
            const modal = document.getElementById('pdfModal');
            modal.style.display = 'none';
            document.getElementById('pdfIframe').src = '';
        }

        // Shortcuts
        function setupKeyboardShortcuts() {
            window.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') {
                    closeImageModal();
                    closePdfModal();
                }
            });
        }
    </script>
</body>

</html>"}}}]}]
